// === Tab: mySketch ===
let particles = [];

function setup() {
    createCanvas(windowWidth, windowHeight);
    background(10, 15, 25);
    // Autonomous initial particle seeding
    for (let i = 0; i < 45; i++) {
        let x = random(width * 0.15, width * 0.85);
        let y = random(height * 0.15, height * 0.85);
        particles.push(new Particle(x, y, random(1.5, 4), random(70, 110)));
    }
}

function draw() {
    // Subtle trailing background for luminous ink effect
    background(8, 12, 20, 28);

    // Autonomous seeding & dynamic audio response
    let needSpawn = (particles.length < 30) || (frameCount % 4 === 0) || window.isBeat || (typeof window.is_silent !== 'undefined' ? !window.is_silent : false);
    if (needSpawn) {
        let px = (typeof window.simulatedMouseX !== 'undefined' && window.simulatedMouseX > 0) ? window.simulatedMouseX : (width * 0.5 + sin(frameCount * 0.03) * width * 0.35);
        let py = (typeof window.simulatedMouseY !== 'undefined' && window.simulatedMouseY > 0) ? window.simulatedMouseY : (height * 0.5 + cos(frameCount * 0.02) * height * 0.35);
        let spawnRate = (typeof window.beatEnergy !== 'undefined' && window.beatEnergy > 0.4) ? 4 : random(1.5, 3.5);
        let spawnAlpha = (typeof window.audioHigh !== 'undefined') ? (75 + window.audioHigh * 45) : 85;
        particles.push(new Particle(px, py, spawnRate, spawnAlpha));
    }

    for (let i = particles.length - 1; i >= 0; i--) {
        particles[i].update(particles);
        particles[i].show();
        if (particles[i].alpha <= 2) {
            particles.splice(i, 1);
        }
    }
}

class Particle {
    constructor(x, y, r, a) {
        this.location = createVector(x, y);
        let angle = noise(x * 0.005, y * 0.005, frameCount * 0.01) * TWO_PI * 2;
        this.velocity = createVector(cos(angle) * 2.2, sin(angle) * 2.2);
        this.alpha = this.palpha = a;
        this.amp = random(2.5, 5.5);
        this.rate = r;
        this.hueShift = random(-30, 30);
    }

    update(p) {
        this.location.add(this.velocity);
        this.alpha -= this.rate;
        if (this.alpha <= this.palpha * 0.25 && this.palpha > 20 && p.length < 120) {
            p.push(new Particle(this.location.x, this.location.y, this.rate * 0.5, this.palpha * 0.5));
        }
    }

    show() {
        noStroke();
        // Luminous ethereal ambient cyan-blue palette
        let lum = min(255, this.alpha * 1.8);
        fill(120 + this.hueShift, 200 + this.hueShift * 0.5, 255, lum);
        ellipse(this.location.x, this.location.y, this.amp);
    }
}

